1	{
2	  "hooks": {
3	    "PreToolUse": [
4	      {
5	        "matcher": "Write|Edit|NotebookEdit",
6	        "hooks": [
7	          {
8	            "type": "command",
9	            "command": "branch=$(git branch --show-current 2>/dev/null); if [ \"$branch\" = 'develop' ] || [ \"$branch\" = 'main' ]; then echo \"BLOCKED: You are on branch '$branch'. Claude Code must not make file changes on develop or main. Switch to a feature branch first.\"; exit 1; fi"
10	          },
11	          {
12	            "type": "command",
13	            "command": "[ -f .claude/hooks/tier2Warn.sh ] && bash .claude/hooks/tier2Warn.sh || true"
14	          }
15	        ]
16	      }
17	    ],
18	    "PostToolUse": [
19	      {
20	        "matcher": "Write",
