35	          },
36	          {
37	            "type": "command",
38	            "command": "[ -f .claude/hooks/registryUpdate.sh ] && bash .claude/hooks/registryUpdate.sh || true"
39	          }
40	        ]
41	      },
42	      {
43	        "matcher": "Write",
44	        "hooks": [
45	          {
46	            "type": "command",
